    executeAction: function (action, id, idx, msg, callback) {
        var vId = id,
            vIdx = idx;
        var params = { id: id };
        var rest = Ext._create(this.rest);
        var rMask = new Ext.LoadMask(this.ownerCt.getEl(), { msg: msg ? msg : "Aguarde..." });
        rMask.show();

        var wnd = this;

        var callbackSuccess = {
            scope: this,
            fn: function (request) {
                rMask.hide();
                if (!request.success) {
                    Ext.MessageBox.show({
                        title: "Erro",
                        msg: request.message,
                        buttons: Ext.MessageBox.OK,
                        icon: Ext.MessageBox.ERROR,
                    });
                } else {
                    if (request.instance) {
                        this._updateRow(vIdx, request.instance.pk);
                    }
                    if (callback) callback(request);
                }
            },
        };

        rest.executeAction(
            action,
            params,
            callbackSuccess,
            {
                fn: function (message) {
                    Ext.Msg.show({
                        title: "Informando",
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: message,
                    });
                },
            },
            {
                fn: function () {
                    rMask.hide();
                },
            }
        );
    },

